#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
set +x
umask 077
local JEV_SIGNING_DIR JEV_SIGNING_HELPER JEV_PROJECT_ROOT
JEV_SIGNING_DIR=$(CDPATH='' cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
JEV_SIGNING_HELPER="$JEV_SIGNING_DIR/packet.mjs"
JEV_PROJECT_ROOT=$(cd -- "$JEV_SIGNING_DIR/../../../.." && pwd)
ENV_FILE="$JEV_SIGNING_DIR/local-state.env"
TOTAL_STAGES=5
if [[ ! -t 0 || ! -t 1 ]]; then
  say "Run this wizard yourself in an interactive local terminal."
  return 1
fi
cd -- "$JEV_PROJECT_ROOT"
say "1. Verify the exact sealed activation packet."
say "2. Create or unlock your encrypted local Ed25519 key."
say "3. Capture current credit and charge-history evidence."
say "4. Review and sign the four exact runtime receipts."
say "5. Verify signatures and evidence locally."
say "Your completed source review and paid authorization are carried forward."
say "This wizard makes no provider calls and creates no attempt ledger."
confirm "Use these five stages?" || return 1
banner "Sign the bounded Jev runtime packet"

stage "Verify the sealed packet"
node "$JEV_SIGNING_HELPER" inspect
say "The accepted bootstrap, dependencies, roster and numerical procedure stay fixed."
pause "Press Enter to set up your local signing key."

stage "Your encrypted local signing key"
ask JEV_SIGNING_KEY_PATH "Encrypted key file [Enter for ~/.local/share/rifd-jev-signing/reviewer-private.pem]:"
if [[ -z "$JEV_SIGNING_KEY_PATH" ]]; then
  JEV_SIGNING_KEY_PATH="${XDG_DATA_HOME:-$HOME/.local/share}/rifd-jev-signing/reviewer-private.pem"
fi
write_env JEV_SIGNING_KEY_PATH "$JEV_SIGNING_KEY_PATH"
if [[ -e "$JEV_SIGNING_KEY_PATH" ]]; then
  say "The existing encrypted Ed25519 key will be reused. It will not be overwritten."
  ask_secret JEV_SIGNING_PASSPHRASE "Enter that key's passphrase:"
else
  say "You are creating your own signing key outside the repository."
  say "Choose a passphrase of at least 12 characters. Keep it in your password manager."
  ask_secret JEV_SIGNING_PASSPHRASE "New signing-key passphrase:"
  ask_secret JEV_SIGNING_PASSPHRASE_CONFIRM "Repeat the passphrase:"
  if [[ "$JEV_SIGNING_PASSPHRASE" != "$JEV_SIGNING_PASSPHRASE_CONFIRM" ]]; then
    unset JEV_SIGNING_PASSPHRASE JEV_SIGNING_PASSPHRASE_CONFIRM
    say "Passphrases differ. No key was created."
    return 1
  fi
fi
printf '%s' "$JEV_SIGNING_PASSPHRASE" | node "$JEV_SIGNING_HELPER" key "$JEV_SIGNING_KEY_PATH"
unset JEV_SIGNING_PASSPHRASE JEV_SIGNING_PASSPHRASE_CONFIRM
say "The private key is encrypted. Only its public key enters the runtime packet."
pause "Keep the fingerprint visible or copy it locally, then press Enter."

stage "Current account evidence"
open_url "https://console.typesafe.ai"
step "Use your signed-in account's balance and billing/usage-history views."
say "Current menu labels were not independently verified; use the views you used previously."
step "Save local screenshots or exports showing available credit and complete charge history."
say "Exclude API keys, payment details and unrelated account data from these captures."
step "Check automatic refill is still off and there are no unexplained or delayed charges."
say "Existing source review, pricing/access, accepted terms and the earlier US$0 actual bill are preserved."
ask JEV_ACCOUNT_CREDIT_USD "Current available credit in USD, such as 5.00:"
ask JEV_BALANCE_CAPTURE "Absolute path to your current balance capture, without surrounding quotes:"
ask JEV_CHARGES_CAPTURE "Absolute path to your current charge-history capture, without surrounding quotes:"
confirm "These captures are current, refill remains off, and all charges are explained and settled?" || return 1
write_env JEV_ACCOUNT_CREDIT_USD "$JEV_ACCOUNT_CREDIT_USD"
write_env JEV_BALANCE_CAPTURE "$JEV_BALANCE_CAPTURE"
write_env JEV_CHARGES_CAPTURE "$JEV_CHARGES_CAPTURE"
ask JEV_RECEIPT_VALID_UNTIL "Receipt expiry in UTC ISO format [Enter for 24 hours from now]:"
write_env JEV_RECEIPT_VALID_UNTIL "$JEV_RECEIPT_VALID_UNTIL"

stage "Review and sign your exact receipt bodies"
node "$JEV_SIGNING_HELPER" prepare "$JEV_SIGNING_KEY_PATH" "$JEV_ACCOUNT_CREDIT_USD" "$JEV_BALANCE_CAPTURE" "$JEV_CHARGES_CAPTURE" "$JEV_RECEIPT_VALID_UNTIL"
step "Open $JEV_SIGNING_DIR/preview/packet.json in your editor and read the four receipt bodies."
say "They bind the tested manifest, unchanged roster, fixed ledger, existing authorization and your current account evidence."
say "The review receipt carries your completed source review. Future native outcomes remain unreviewed."
confirm "I am the authorized reviewer, control the displayed key, and reviewed these exact bodies. Sign them?" || return 1
ask_secret JEV_SIGNING_PASSPHRASE "Unlock your signing key to sign these four receipts:"
printf '%s' "$JEV_SIGNING_PASSPHRASE" | node "$JEV_SIGNING_HELPER" sign "$JEV_SIGNING_KEY_PATH"
unset JEV_SIGNING_PASSPHRASE

stage "Verify the signed packet"
node "$JEV_SIGNING_HELPER" verify
finish
say "Runtime receipts are ready for Codex to check. The wizard did not start inference."
say "Reply: The signing wizard completed. Keep your passphrase and private key private."
}

run_wizard "$@"; exit
